pub fn replaceDotAndUnderscore(mut in_txt: Tpl::Text, in_a_str: &ArcStr) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match in_a_str {
        i_name => {
            let mut txt = in_txt;
            let mut ret_1;
            let mut l_str__dots;
            let mut ret_3;
            let mut l_str__underscores;
            let mut ret_4;
            ret_1 = System::stringReplace(i_name.clone(), literal!("."), literal!("_"))?;
            l_str__dots = Tpl::writeStr((*Tpl::emptyTxt).clone(), ret_1)?;
            ret_3 = System::stringReplace(Tpl::textString(l_str__dots)?, literal!("_"), literal!("__"))?;
            l_str__underscores = Tpl::writeStr((*Tpl::emptyTxt).clone(), ret_3)?;
            ret_4 = System::unquoteIdentifier(Tpl::textString(l_str__underscores)?);
            txt = Tpl::writeStr(txt, ret_4)?;
            Ok(txt)
        }
        _ => Err("replaceDotAndUnderscore: no case matched"),
    } }
}

pub fn underscorePath<'a>(
    mut in_txt: Tpl::Text,
    mut in_a_path: &'a metamodelica::Ref<Absyn::Path>,
) -> Result<Tpl::Text> {
    '__tco: loop {
        break ::match_deref::match_deref! { match in_a_path {
            Deref @ Absyn::Path::QUALIFIED { name: i_name, path: i_path, .. } => {
                let mut txt = in_txt;
                txt = replaceDotAndUnderscore(txt, i_name)?;
                txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("_") }))?;
                (in_txt, in_a_path) = (txt, i_path);
                continue '__tco;
            }
            Deref @ Absyn::Path::IDENT { name: i_name, .. } => {
                let mut txt = in_txt;
                txt = replaceDotAndUnderscore(txt, i_name)?;
                Ok(txt)
            }
            Deref @ Absyn::Path::FULLYQUALIFIED { path: i_path, .. } => {
                let mut txt = in_txt;
                (in_txt, in_a_path) = (txt, i_path);
                continue '__tco;
            }
            _ => {
                let mut txt = in_txt;
                Ok(txt)
            }
            _ => Err("underscorePath: no case matched"),
        } };
    }
}
